import 'fantd/src/swipe-model/style/index.less';
import { SwipeModel } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';

class Component extends React.Component {

    render() {
        return (
            <div style={{width:400,height:400}}>
                <SwipeModel
                    initIndex={0}
                    getEvent={(push,pop)=>{
                        /*
                        push(1);//右滑动到页面1
                        pop();//左滑回退到上一个页面
                       */

                        setTimeout(()=>{
                            push(1);
                            setTimeout(()=>{
                                push(2);
                                setTimeout(()=>{
                                    pop();
                                    setTimeout(()=>{
                                        pop()
                                    },2000)
                                },2000)
                            },2000)
                        },2000)
                    }}
                >
                    <div style={{background:"green",height:"100%"}}>页面1</div>
                    <div style={{background:"red",height:"100%"}}>页面2</div>
                    <div style={{background:"black",height:"100%"}}>页面3</div>
                </SwipeModel>
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



